transparentproxy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

contract TransparentProxy {
    // Storage slot constants per EIP-1967

    // Slot for the implementation address:
    // bytes32(uint256(keccak256('eip1967.proxy.implementation')) - 1)
    bytes32 private constant _IMPLEMENTATION_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    // Slot for the admin address:
    // bytes32(uint256(keccak256('eip1967.proxy.admin')) - 1)
    bytes32 private constant _ADMIN_SLOT =
        0xb53127684a568b3173ae13b9f8a6016e019a9c8f64f10d9a79d4c24321f3c7a2;

    // Modifier to restrict access to admin-only functions.
    modifier ifAdmin() {
        require(msg.sender == _getAdmin(), "TransparentProxy: caller is not admin");
        _;
    }

    /**
     * @notice The constructor sets the initial implementation and admin.
     * Optionally, initialization data is passed to the implementation.
     * @param _implementation The address of the initial logic contract.
     * @param _data Data for initializing the logic contract (typically the encoded initialize() call).
     */
    constructor(address _implementation, bytes memory _data) payable {
        _setAdmin(msg.sender);
        _setImplementation(_implementation);
        if (_data.length > 0) {
            // Delegatecall to initialize the logic contract.
            (bool success, ) = _implementation.delegatecall(_data);
            require(success, "Initialization failed");
        }
    }

    // Admin functions

    /**
     * @notice Upgrades the proxy to a new implementation.
     * @param newImplementation The address of the new logic contract.
     */
    function upgradeTo(address newImplementation) external ifAdmin {
        require(newImplementation != address(0), "New implementation is zero address");
        _setImplementation(newImplementation);
    }

    /**
     * @notice Changes the admin of the proxy.
     * @param newAdmin The address of the new admin.
     */
    function changeAdmin(address newAdmin) external ifAdmin {
        require(newAdmin != address(0), "New admin is zero address");
        _setAdmin(newAdmin);
    }

    /**
     * @notice Returns the current admin (admin-only).
     */
    function admin() external view ifAdmin returns  (address) {
        return _getAdmin();
    }

    /**
     * @notice Returns the current implementation address (admin-only).
     */
    function implementation() external view ifAdmin returns (address) {
        return _getImplementation();
    }

    // Fallback: delegate all other calls to the logic contract

    fallback() external payable {
        _fallback();
    }

    receive() external payable {
        _fallback();
    }

    // Delegates the current call to the implementation.
    function _delegate(address impl) internal {
        assembly {
            // Copy msg.data.
            calldatacopy(0, 0, calldatasize())
            // Delegatecall to the implementation.
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            // Copy the returned data.
            let size := returndatasize()
            returndatacopy(0, 0, size)
            // Revert or return the data based on the call result.
            switch result
            case 0 { revert(0, size) }
            default { return(0, size) }
        }
    }

    // Fallback function that delegates calls to the implementation,
    // unless the caller is the admin (to prevent accidental calls).
     
    function _fallback() internal {
        if (msg.sender == _getAdmin()) {
            revert("TransparentProxy: admin cannot fallback to proxy target");
        }
        _delegate(_getImplementation());
    }

    
    // Internal functions to manage the implementation and admin storage slots.

    function _getImplementation() internal view returns (address impl) {
        bytes32 slot = _IMPLEMENTATION_SLOT;
        assembly { impl := sload(slot) }
    }

    function _setImplementation(address newImplementation) internal {
        bytes32 slot = _IMPLEMENTATION_SLOT;
        assembly { sstore(slot, newImplementation) }
    }

    function _getAdmin() internal view returns (address adm) {
        bytes32 slot = _ADMIN_SLOT;
        assembly { adm := sload(slot) }
    }

    function _setAdmin(address newAdmin) internal {
        bytes32 slot = _ADMIN_SLOT;
        assembly { sstore(slot, newAdmin) }
    }
}

